-- Column-only test fixtures; no user records or credentials.
create schema private;
create table private.asaas_refund_requests (id uuid,reservation_id uuid,payment_id uuid,requested_by uuid,amount numeric,status text,claim_token uuid,attempts integer,error_code text,provider_evidence jsonb,created_at timestamp with time zone,updated_at timestamp with time zone,provider_transfer_id text,transfer_status text,transfer_fail_reason text,transfer_observed_at timestamp with time zone,transfer_event_id text,provider_pix_transaction_id text,pix_status text,pix_refusal_reason text,pix_observed_at timestamp with time zone,pix_event_id text,is_current boolean,previous_request_id uuid,retry_evidence jsonb,baseline_refunded_amount numeric);
create table private.asaas_split_contracts (reservation_id uuid,issuer_account_id text,issuer_wallet_id text,split_wallet_id text,commission_rate numeric,created_at timestamp with time zone);
create table private.financial_movements (id uuid,partner_id uuid,reservation_id uuid,source_type text,source_id uuid,kind text,channel text,amount numeric,occurred_at timestamp with time zone,date_quality text,description text,created_at timestamp with time zone,evidence_source text);
create table public.accounting_ledger (id uuid,reservation_id uuid,partner_id uuid,entry_type text,amount numeric,fiscal_amount numeric,accounting_month character,description text,metadata jsonb,created_at timestamp with time zone);
create table public.cancellation_requests (id uuid,reservation_id uuid,requested_by uuid,requester_type text,reason text,within_deadline boolean,resolution text,status text,reviewed_by uuid,reviewed_at timestamp with time zone,created_at timestamp with time zone,policy_version text,policy_accepted_at timestamp with time zone,resolution_details jsonb);
create table public.financial_provider_settlements (id uuid,partner_id uuid,reservation_id uuid,provider_event_id text,partner_amount numeric,commission_amount numeric,confirmed_at timestamp with time zone,metadata jsonb);
create table public.marketplace_settings (id boolean,marketplace_enabled boolean,new_partner_applications_enabled boolean,vouchers_enabled boolean,real_money_enabled boolean,automatic_partner_approval boolean,notification_emails boolean,default_commission_rate numeric,asaas_reference_fee_rate numeric,cancellation_hours integer,voucher_validity_days integer,voucher_compatibility_window_hours integer,voucher_minimum_compatible_dates integer,voucher_extension_days integer,updated_at timestamp with time zone,updated_by uuid,asaas_pix_fixed_fee numeric,asaas_card_fixed_fee numeric,asaas_card_percentage_fee numeric);
create table public.monthly_payment_stages (id uuid,monthly_cycle_id uuid,reservation_id uuid,stage text,status text,amount_required numeric,amount_paid numeric,available_from timestamp with time zone,due_at timestamp with time zone,paid_at timestamp with time zone,created_at timestamp with time zone,updated_at timestamp with time zone);
create table public.occurrence_transfer_requests (id uuid,reservation_id uuid,original_occurrence_id uuid,replacement_occurrence_id uuid,target_schedule_slot_id uuid,requested_by uuid,requested_by_type text,reason text,status text,proposed_by uuid,proposed_at timestamp with time zone,decided_by uuid,decided_at timestamp with time zone,resolution_notes text,refund_ledger_id uuid,created_at timestamp with time zone,updated_at timestamp with time zone,proposal_revision integer,proposed_starts_at timestamp with time zone,proposed_ends_at timestamp with time zone,changes_accepted_at timestamp with time zone,changes_accepted_by uuid,accepted_proposal_revision integer);
create table public.partner_payment_configs (partner_id uuid,asaas_subaccount_id text,asaas_wallet_id text,asaas_status text,card_enabled boolean,pix_direct_enabled boolean,manual_pix_fallback boolean,updated_at timestamp with time zone);
create table public.payment_intents (id uuid,reservation_id uuid,method text,provider text,status text,amount numeric,currency character,external_reference text,provider_payment_id text,provider_checkout_id text,checkout_url text,idempotency_key uuid,metadata jsonb,confirmed_at timestamp with time zone,created_at timestamp with time zone,updated_at timestamp with time zone,monthly_payment_stage_id uuid);
create table public.reservation_occurrences (id uuid,reservation_id uuid,schedule_slot_id uuid,starts_at timestamp with time zone,ends_at timestamp with time zone,allocated_value numeric,status text,created_at timestamp with time zone,updated_at timestamp with time zone,rescheduled_from_occurrence_id uuid,transfer_request_id uuid);
create table public.reservation_participants (id uuid,reservation_id uuid,profile_id uuid,amount_due numeric,amount_paid numeric,status text,created_at timestamp with time zone,updated_at timestamp with time zone,payment_role text,monthly_payment_stage_id uuid,manual_settlement_method text,manual_settled_by uuid,manual_settled_at timestamp with time zone,manual_settlement_reference text,manual_settlement_notes text);
create table public.venue_spaces (id uuid,venue_id uuid,name text,type text,floor text,capacity integer,base_price numeric,monthly_price numeric,lights boolean,covered boolean,active boolean,maintenance_date date,created_at timestamp with time zone,updated_at timestamp with time zone);
create table public.venues (id uuid,partner_id uuid,slug text,name text,street text,street_number text,neighborhood text,city text,state character,zip text,timezone text,rating numeric,reviews_count integer,amenities text[],published boolean,created_at timestamp with time zone,updated_at timestamp with time zone);
