create table public.vouchers (id uuid,code text,title text,origin text,issuer_user_id uuid,partner_id uuid,owner_user_id uuid,source_reservation_id uuid,discount_type text,discount_value numeric,minimum_reservation_value numeric,booking_scope text,single_use boolean,valid_from timestamp with time zone,expires_at timestamp with time zone,status text,original_booking_mode text,original_start_time time without time zone,original_period text,compatibility_window_hours integer,partner_liability boolean,archived_reason text,created_at timestamp with time zone,updated_at timestamp with time zone,extension_count integer,last_extended_at timestamp with time zone,extension_reason text,event_date date,event_start_time time without time zone,event_end_time time without time zone,cancellation_flow_version text);
create table public.webhook_events (id uuid,provider text,provider_event_id text,event_type text,payload jsonb,status text,attempts integer,last_error text,received_at timestamp with time zone,processed_at timestamp with time zone,processing_reason text);

-- Contract fixture for the existing effective-voucher view. Its own business rules are unchanged.
create view public.marketplace_voucher_effective_state as select x.*,p.trade_name partner_name,u.display_name owner_name,
x.status effective_status,x.expires_at+interval '7 days' effective_expires_at,0::integer used_count,0::integer reserved_count,null::timestamptz last_used_at
from public.vouchers x left join public.partners p on p.id=x.partner_id left join public.profiles u on u.id=x.owner_user_id;
